package com.nimbusbill.customer.controller;
import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.service.PricingService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/v1") public class PricingController{
 private final PricingService service;public PricingController(PricingService service){this.service=service;}
 @PostMapping("/pricing-plans") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER')") ResponseEntity<PricingPlanResponse> create(@Valid @RequestBody PricingPlanRequest r,Principal principal,@RequestHeader(value="X-Actor",required=false) String localActor){PricingPlanResponse p=service.create(r,actor(principal,localActor));return ResponseEntity.created(URI.create("/api/v1/pricing-plans/"+p.id())).body(p);}
 @GetMapping("/pricing-plans") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','OPERATIONS','AUDITOR','READ_ONLY')") List<PricingPlanResponse> list(){return service.list();}
 @GetMapping("/pricing-plans/{id}") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','OPERATIONS','AUDITOR','READ_ONLY')") PricingPlanResponse get(@PathVariable UUID id){return service.get(id);}
 @PostMapping("/pricing-plans/{planId}/versions/{versionId}/submit") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER')") PricingPlanResponse submit(@PathVariable UUID planId,@PathVariable UUID versionId){return service.submit(planId,versionId);}
 @PostMapping("/pricing-plans/{planId}/versions/{versionId}/approve") @PreAuthorize("hasAnyRole('ADMIN','FINANCE')") PricingPlanResponse approve(@PathVariable UUID planId,@PathVariable UUID versionId,Principal principal,@RequestHeader(value="X-Actor",required=false) String localActor){return service.approve(planId,versionId,actor(principal,localActor));}
 @PostMapping("/pricing-plans/{planId}/versions/{versionId}/reject") @PreAuthorize("hasAnyRole('ADMIN','FINANCE')") PricingPlanResponse reject(@PathVariable UUID planId,@PathVariable UUID versionId,Principal principal,@RequestHeader(value="X-Actor",required=false) String localActor){return service.reject(planId,versionId,actor(principal,localActor));}
 @PostMapping("/pricing-plans/{planId}/versions/{versionId}/activate") @PreAuthorize("hasRole('ADMIN')") PricingPlanResponse activate(@PathVariable UUID planId,@PathVariable UUID versionId){return service.activate(planId,versionId);}
 @PostMapping("/pricing/preview") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','OPERATIONS','AUDITOR','READ_ONLY')") PricingPreviewResponse preview(@Valid @RequestBody PricingPreviewRequest r){return service.preview(r);}
 private String actor(Principal p,String local){return p==null||"local-admin".equals(p.getName())?(local==null||local.isBlank()?"local-admin":local):p.getName();}
}
